1	"use server";
2	
3	/**
4	 * Admin-only management of COMPANY mailboxes on the Nxeon domain (admin@,
5	 * support@, santino@, and any more the admin creates) — free.
6	 *
7	 * These are deliberately decoupled from the customer email-hosting model
8	 * (EmailSubscription / EmailPlan / Mailbox): a company mailbox is a
9	 * `CompanyMailbox` row + a Mailcow mailbox, and nothing else. No wallet debit,
10	 * no plan limit, no subscription — "free" is structural, not a discount.
11	 *
12	 * SECURITY. Every export authenticates INSIDE the function before touching
13	 * Mailcow or the database, and returns a typed { ok, error? } result rather
14	 * than throwing raw internals at the client. Listing is reachable via EITHER
15	 * the companyInbox or companyMailboxes grant (lib/staff-grants.ts) — an
16	 * EMPLOYEE granted just "read the company inbox" can still see which
17	 * addresses exist to pick from. CRUD/credential-reveal/reset stay gated to
18	 * the stricter companyMailboxes grant specifically. ADMIN always passes both.
19	 * The mailbox password is generated server-side, stored AES-256-GCM encrypted
20	 * (lib/crypto-box), and only ever returned on explicit reveal/reset.
21	 */
22	import { db } from "./db";
23	import { requireAnyGrant, requireGrant } from "./staff-grants";
24	import { encryptSecret, decryptSecret } from "./crypto-box";
25	import { randomBytes } from "node:crypto";
26	import {
27	  COMPANY_MAIL_DOMAIN,
28	  DEFAULT_COMPANY_LOCALPARTS,
29	  type CompanyMailboxRow,
30	} from "./company-mail-core";
31	import type { MailboxInfo } from "./mail/types";
32	import {
33	  mailcowConfigured,
34	  mcDomainExists,
35	  mcCreateDomain,
36	  mcCreateMailbox,
37	  mcDeleteMailbox,
38	  mcSetMailboxPassword,
39	  mcListMailboxes,
40	  isMailcowUnreachable,
41	} from "./mailcow";
42	
43	/** Default quota for a company mailbox. */
44	const DEFAULT_QUOTA_MB = 2048;
45	
46	type Ok<T> = { ok: true } & T;
47	type Err = { ok: false; error: string };
48	
49	/** Lower-case, validate a local part (the bit before @). */
50	function normalizeLocalPart(raw: string): string | null {
51	  const lp = String(raw ?? "").trim().toLowerCase();
52	  // RFC-ish, conservative: start/end alphanumeric, dots/dashes/underscores inside.
53	  if (!/^[a-z0-9](?:[a-z0-9._-]{0,61}[a-z0-9])?$/.test(lp)) return null;
54	  return lp;
55	}
56	
57	/** A strong, URL-safe mailbox password. */
58	function generatePassword(): string {
59	  return randomBytes(18).toString("base64url");
60	}
61	
62	/** Map an unknown error to a safe, user-facing string. */
63	function safeMailError(err: unknown): string {
64	  if (isMailcowUnreachable(err)) {
65	    return "The mail server is unreachable right now. Please try again shortly.";
66	  }
67	  const msg = err instanceof Error ? err.message : String(err);
68	  // Mailcow "danger" messages are already terse and safe to surface.
69	  return msg && msg.length < 200 ? msg : "The mail server rejected the request.";
70	}
71	
72	/** Ensure the company domain exists in Mailcow (idempotent, best-effort create). */
73	async function ensureDomain(): Promise<void> {
74	  if (await mcDomainExists(COMPANY_MAIL_DOMAIN)) return;
75	  await mcCreateDomain(COMPANY_MAIL_DOMAIN);
76	}
77	
78	async function audit(userId: string, action: string, detail: string): Promise<void> {
79	  try {
80	    await db.auditLog.create({ data: { userId, action, detail } });
81	  } catch {
82	    /* audit is best-effort — never fail the operation on a logging error */
83	  }
84	}
85	
86	/**
87	 * List every company mailbox. Merges live quota usage from Mailcow when it is
88	 * reachable; falls back to DB-only rows (usedMB: null) if it is not.
89	 */
90	export async function listCompanyMailboxes(): Promise<CompanyMailboxRow[]> {
91	  await requireAnyGrant(["companyInbox", "companyMailboxes"]);
92	  const rows = await db.companyMailbox.findMany({ orderBy: { address: "asc" } });
93	
94	  const usedByAddress = new Map<string, number>();
95	  try {
96	    if (mailcowConfigured()) {
97	      const live = await mcListMailboxes(COMPANY_MAIL_DOMAIN);
98	      for (const m of live) {
99	        usedByAddress.set(m.address.toLowerCase(), Math.round(m.quotaUsedBytes / (1024 * 1024)));
100	      }
101	    }
102	  } catch {
103	    /* Mailcow unreachable — show DB rows without live usage */
104	  }
105	
106	  return rows.map((r) => ({
107	    id: r.id,
108	    address: r.address,
109	    label: r.label,
110	    quotaMB: r.quotaMB,
111	    status: r.status,
112	    createdAt: r.createdAt.toISOString(),
113	    usedMB: usedByAddress.has(r.address.toLowerCase()) ? usedByAddress.get(r.address.toLowerCase())! : null,
114	  }));
115	}
116	
117	/**
118	 * The company mailboxes as `MailboxInfo` for the admin webmail switcher. This is
119	 * the admin-portal equivalent of the customer `getMailboxes()` — it is what keeps
120	 * company mail OUT of the customer switcher (that one no longer lists them).
121	 * ADMIN-only (delegates to the guarded `listCompanyMailboxes`).
122	 */
123	export async function listCompanyMailboxInfos(): Promise<MailboxInfo[]> {
124	  await requireAnyGrant(["companyInbox", "companyMailboxes"]);
125	  const rows = await listCompanyMailboxes();
126	  return rows.map((r) => ({
127	    address: r.address,
128	    usedBytes: (r.usedMB ?? 0) * 1024 * 1024,
129	    quotaBytes: r.quotaMB * 1024 * 1024,
130	  }));
131	}
132	
133	/**
134	 * Create a free company mailbox. Provisions it on Mailcow, stores the encrypted
135	 * password, and returns the generated password ONCE (so the admin can hand it to
136	 * whoever owns the address / sign in to webmail).
137	 */
138	export async function createCompanyMailbox(
139	  localPartRaw: string,
140	  labelRaw?: string
141	): Promise<Ok<{ address: string; password: string }> | Err> {
142	  const admin = await requireGrant("companyMailboxes");
143	  if (!mailcowConfigured()) {
144	    return { ok: false, error: "Mail hosting is not configured (MAILCOW_API_URL / MAILCOW_API_KEY)." };
145	  }
146	  const localPart = normalizeLocalPart(localPartRaw);
147	  if (!localPart) {
148	    return { ok: false, error: "Enter a valid mailbox name (letters, numbers, dots, dashes)." };
149	  }
150	  const address = `${localPart}@${COMPANY_MAIL_DOMAIN}`;
151	
152	  const existing = await db.companyMailbox.findUnique({ where: { address } });
153	  if (existing) return { ok: false, error: `${address} already exists.` };
154	
155	  const label = labelRaw?.trim() ? labelRaw.trim().slice(0, 80) : null;
156	  const password = generatePassword();
157	
158	  try {
159	    await ensureDomain();
160	    await mcCreateMailbox({
161	      localPart,
162	      domain: COMPANY_MAIL_DOMAIN,
163	      name: label ?? localPart,
164	      password,
165	      quotaMB: DEFAULT_QUOTA_MB,
166	    });
167	  } catch (err) {
168	    return { ok: false, error: safeMailError(err) };
169	  }
170	
171	  await db.companyMailbox.create({
172	    data: {
173	      address,
174	      label,
175	      passwordEnc: encryptSecret(password),
176	      quotaMB: DEFAULT_QUOTA_MB,
177	      status: "ACTIVE",
178	      createdById: admin.id,
179	    },
180	  });
181	  await audit(admin.id, "company_mailbox.create", address);
182	
183	  return { ok: true, address, password };
184	}
185	
186	/**
187	 * Create any of the default starter mailboxes (admin@, support@, santino@) that
188	 * don't already exist. Returns the created addresses + their one-time passwords.
189	 */
190	export async function createDefaultCompanyMailboxes(): Promise<
191	  Ok<{ created: Array<{ address: string; password: string }>; skipped: string[] }> | Err
192	> {
193	  await requireGrant("companyMailboxes");
194	  if (!mailcowConfigured()) {
195	    return { ok: false, error: "Mail hosting is not configured (MAILCOW_API_URL / MAILCOW_API_KEY)." };
196	  }
197	  const created: Array<{ address: string; password: string }> = [];
198	  const skipped: string[] = [];
199	  for (const lp of DEFAULT_COMPANY_LOCALPARTS) {
200	    const res = await createCompanyMailbox(lp);
201	    if (res.ok) created.push({ address: res.address, password: res.password });
202	    else skipped.push(`${lp}@${COMPANY_MAIL_DOMAIN}`);
203	  }
204	  return { ok: true, created, skipped };
205	}
206	
207	/** Reveal an existing mailbox's stored password (decrypted). */
208	export async function revealCompanyMailboxPassword(
209	  id: string
210	): Promise<Ok<{ address: string; password: string }> | Err> {
211	  const admin = await requireGrant("companyMailboxes");
212	  const box = await db.companyMailbox.findUnique({ where: { id } });
213	  if (!box) return { ok: false, error: "Mailbox not found." };
214	  const password = decryptSecret(box.passwordEnc);
215	  if (!password) return { ok: false, error: "No stored password for this mailbox." };
216	  await audit(admin.id, "company_mailbox.reveal", box.address);
217	  return { ok: true, address: box.address, password };
218	}
219	
220	/** Reset a mailbox password to a new strong value; returns it once. */
221	export async function resetCompanyMailboxPassword(
222	  id: string
223	): Promise<Ok<{ address: string; password: string }> | Err> {
224	  const admin = await requireGrant("companyMailboxes");
225	  if (!mailcowConfigured()) return { ok: false, error: "Mail hosting is not configured." };
226	  const box = await db.companyMailbox.findUnique({ where: { id } });
227	  if (!box) return { ok: false, error: "Mailbox not found." };
228	  const password = generatePassword();
229	  try {
230	    await mcSetMailboxPassword(box.address, password);
231	  } catch (err) {
232	    return { ok: false, error: safeMailError(err) };
233	  }
234	  await db.companyMailbox.update({ where: { id }, data: { passwordEnc: encryptSecret(password), status: "ACTIVE" } });
235	  await audit(admin.id, "company_mailbox.reset_password", box.address);
236	  return { ok: true, address: box.address, password };
237	}
238	
239	/** Delete a company mailbox from Mailcow and the database. */
240	export async function deleteCompanyMailbox(id: string): Promise<{ ok: true } | Err> {
241	  const admin = await requireGrant("companyMailboxes");
242	  const box = await db.companyMailbox.findUnique({ where: { id } });
243	  if (!box) return { ok: false, error: "Mailbox not found." };
244	  if (mailcowConfigured()) {
245	    try {
246	      await mcDeleteMailbox(box.address);
247	    } catch (err) {
248	      // If Mailcow refused (not merely unreachable), surface it; don't orphan the row.
249	      if (!isMailcowUnreachable(err)) return { ok: false, error: safeMailError(err) };
250	    }
251	  }
252	  await db.companyMailbox.delete({ where: { id } });
253	  await audit(admin.id, "company_mailbox.delete", box.address);
254	  return { ok: true };
255	}
