1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import { hasAreaAccess } from "./staff-grants";
9	import { writeTicketReply } from "./reply-core";
10	import { mirrorNewTicketToDiscord, mirrorTicketReplyToDiscord } from "./discord-bridge";
11	import { validateTicketAttachmentBytes, MAX_TICKET_ATTACHMENT_BYTES } from "./ticket-attachment";
12	
13	/**
14	 * SUPPORT-ROLE ENFORCEMENT (2026-07-27 admin audit).
15	 *
16	 * `lib/rbac.ts` grants the `support` area to SUPPORT and ADMIN, `/admin/support`
17	 * and `/admin/support/[id]` both gate on `requireArea("support")`, and the admin
18	 * layout renders the desk in a SUPPORT agent's sidebar. Every WRITE behind those
19	 * pages, however, still required ADMIN:
20	 *
21	 *   - `setTicketPriority` called `requireAdmin()`. `PrioritySelect` does not
22	 *     catch, so a SUPPORT agent picked "Urgent", the throw vanished into an
23	 *     unhandled transition, and the `<select>` (uncontrolled, `defaultValue`)
24	 *     kept showing the new value. The control reported success and did nothing.
25	 *   - `setTicketStatus` and `replyTicket` applied the CUSTOMER ownership test
26	 *     (`ticket.userId !== user.id && role !== "ADMIN"`), so a SUPPORT agent could
27	 *     neither close nor answer a ticket that was not their own — i.e. any ticket.
28	 *
29	 * So the entire job of the SUPPORT role was a read-only page with three controls
30	 * that silently refused. `lib/actions-chat.ts` — the other half of the same area —
31	 * has always gated correctly on `requireArea("support")`; the ticket desk simply
32	 * was never updated when RBAC landed. These now use the same rule. No role gains
33	 * anything `lib/rbac.ts` did not already declare, and CUSTOMER is unaffected:
34	 * a customer still reaches only their own ticket.
35	 */
36	/**
37	 * The session behind a ticket action, plus whether they are support staff.
38	 *
39	 * Named `require*` deliberately. `test/auth-lockouts.test.ts` enforces that every
40	 * export of a "use server" file — each of which is a network-callable endpoint
41	 * anyone can POST to — calls a recognised guard INSIDE the function, and it
42	 * recognises guards by the `require*`/`owned*`/`assert*`/`resolve*` convention.
43	 * This helper was `ticketActor`, which guarded correctly but did not LOOK like a
44	 * guard, so the tripwire reported three genuinely-safe endpoints as unguarded.
45	 *
46	 * The fix was the name, not the rule: widening the rule to accept arbitrary
47	 * helper names would let a future function that guards nothing pass the same
48	 * check. A guard should be recognisable as one.
49	 */
50	async function requireTicketActor(): Promise<{ id: string; isSupportStaff: boolean }> {
51	  const user = await requireUser();
52	  return { id: user.id, isSupportStaff: await hasAreaAccess(user, "supportTickets") };
53	}
54	
55	export async function createTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
56	  const user = await requireUser();
57	  const parsed = z
58	    .object({
59	      subject: z.string().min(3).max(150),
60	      body: z.string().min(5).max(10000),
61	      priority: z.enum(["LOW", "NORMAL", "HIGH", "URGENT"]).default("NORMAL"),
62	    })
63	    .safeParse({
64	      subject: formData.get("subject"),
65	      body: formData.get("body"),
66	      priority: formData.get("priority") ?? "NORMAL",
67	    });
68	  if (!parsed.success) return { error: "Subject (3+) and message (5+) required." };
69	
70	  const ticket = await db.ticket.create({
71	    data: {
72	      subject: parsed.data.subject,
73	      priority: parsed.data.priority,
74	      userId: user.id,
75	      messages: { create: { body: parsed.data.body, authorId: user.id, isStaff: false } },
76	    },
77	  });
78	  const admins = await db.user.findMany({ where: { role: "ADMIN" } });
79	  await db.notification.createMany({
80	    data: admins.map((a) => ({
81	      userId: a.id,
82	      title: `New ticket: ${parsed.data.subject}`,
83	      href: `/admin/support/${ticket.id}`,
84	    })),
85	  });
86	  // Discord bridge (Phase 1 mirror): best-effort, never blocks ticket creation
87	  // or the redirect below — see lib/discord-bridge.ts's top-of-file comment.
88	  await mirrorNewTicketToDiscord(ticket.id);
89	  redirect(`/dashboard/support/${ticket.id}`);
90	}
91	
92	export async function replyTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
93	  const user = await requireTicketActor();
94	  const ticketId = String(formData.get("ticketId") ?? "");
95	  const body = String(formData.get("body") ?? "").trim();
96	
97	  // Ownership guard, kept directly in this "use server" boundary — every
98	  // export of this file is a public network endpoint (see this file's
99	  // top-of-file comment on the exact RBAC bug that made that non-obvious).
100	  // `writeTicketReply` (lib/reply-core.ts) re-checks this same thing before
101	  // writing, so this is deliberate defense-in-depth, not the only place it's
102	  // enforced — but a reviewer of THIS file should still see proof a customer
103	  // can only reply to their own ticket without having to trust an opaque
104	  // helper elsewhere.
105	  const ticketOwner = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
106	  if (!ticketOwner) return { error: "Ticket not found." };
107	  if (ticketOwner.userId !== user.id && !user.isSupportStaff) return { error: "Forbidden." };
108	
109	  // Optional single attachment (paste-image or file-picker upload). The same
110	  // ownership guard above already covers who may attach — a customer can only
111	  // ever reach here for their own ticket, staff for any ticket they can open.
112	  let attachment: { mime: string; name: string; size: number; data: Buffer } | undefined;
113	  const file = formData.get("file");
114	  if (file instanceof File && file.size > 0) {
115	    if (file.size > MAX_TICKET_ATTACHMENT_BYTES) {
116	      return { error: "File is larger than 10 MB." };
117	    }
118	    const bytes = Buffer.from(await file.arrayBuffer());
119	    const check = validateTicketAttachmentBytes(bytes, file.type, file.name);
120	    if (!check.ok) return { error: check.error };
121	    attachment = { mime: check.mime, name: file.name.slice(0, 200) || "attachment", size: check.bytes.length, data: check.bytes };
122	  }
123	
124	  const result = await writeTicketReply({
125	    actorId: user.id,
126	    actorIsSupportStaff: user.isSupportStaff,
127	    ticketId,
128	    body,
129	    attachment,
130	  });
131	  if (result.error) return { error: result.error };
132	
133	  // Discord bridge (Phase 1 mirror): best-effort. This reply was written from
134	  // the web dashboard, never from Discord (Discord-originated replies go
135	  // through app/api/webhooks/discord/route.ts, which calls writeTicketReply
136	  // directly and does NOT mirror — otherwise a Discord reply would echo right
137	  // back into the same Discord thread it came from).
138	  const mirrorBody = body || (attachment ? `📎 ${attachment.name} (attachment — view in the dashboard)` : body);
139	  await mirrorTicketReplyToDiscord(ticketId, mirrorBody, Boolean(result.isStaff));
140	
141	  revalidatePath(`/dashboard/support/${ticketId}`);
142	  revalidatePath(`/admin/support/${ticketId}`);
143	  return {};
144	}
145	
146	/**
147	 * A TypeScript parameter type is a compile-time comment on a network endpoint.
148	 *
149	 * Every export of this file is POST-able with any JSON the caller likes, so the
150	 * `"OPEN" | "CLOSED"` annotations below constrained the components and nothing
151	 * else. `TicketStatus` also contains ANSWERED and CUSTOMER_REPLY — both writable
152	 * here — so a customer could stamp their own ticket ANSWERED and drop it out of
153	 * the support queue's "needs a reply" view without anyone having replied. Values
154	 * outside the enum reached Prisma and threw, which surfaces as a server error
155	 * page rather than a message. Both are fixed by validating at the boundary.
156	 */
157	const TICKET_STATUS_CHOICES = ["OPEN", "CLOSED"] as const;
158	const TICKET_PRIORITY_CHOICES = ["LOW", "NORMAL", "HIGH", "URGENT"] as const;
159	
160	export async function setTicketStatus(ticketId: string, status: "OPEN" | "CLOSED") {
161	  const user = await requireTicketActor();
162	  if (!TICKET_STATUS_CHOICES.includes(status as (typeof TICKET_STATUS_CHOICES)[number])) {
163	    throw new Error("A ticket can only be reopened or closed from here.");
164	  }
165	  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
166	  if (!ticket) throw new Error("Not found");
167	  if (ticket.userId !== user.id && !user.isSupportStaff) throw new Error("Forbidden");
168	  await db.ticket.update({ where: { id: ticketId }, data: { status } });
169	  revalidatePath(`/dashboard/support`);
170	  revalidatePath(`/dashboard/support/${ticketId}`);
171	  revalidatePath(`/admin/support`);
172	  revalidatePath(`/admin/support/${ticketId}`);
173	}
174	
175	export async function setTicketPriority(ticketId: string, priority: "LOW" | "NORMAL" | "HIGH" | "URGENT") {
176	  const user = await requireTicketActor();
177	  // Triage is a staff-only judgement — a customer must not be able to promote
178	  // their own ticket to URGENT — but it IS the support desk's job.
179	  if (!user.isSupportStaff) throw new Error("Forbidden");
180	  if (!TICKET_PRIORITY_CHOICES.includes(priority as (typeof TICKET_PRIORITY_CHOICES)[number])) {
181	    throw new Error("Priority must be one of: LOW, NORMAL, HIGH, URGENT.");
182	  }
183	  await db.ticket.update({ where: { id: ticketId }, data: { priority } });
184	  revalidatePath(`/admin/support`);
185	  revalidatePath(`/admin/support/${ticketId}`);
186	}
187	
188	/** How long after sending a message its author may still edit it. */
189	const EDIT_WINDOW_MS = 5 * 60_000;
190	
191	/**
192	 * Edit the body of your own message, within 5 minutes of sending it, while the
193	 * ticket is open. The 5-minute window is enforced HERE against `createdAt` —
194	 * never trust a client-side countdown, which only controls whether the "Edit"
195	 * affordance is shown. `editedAt` is set so both the admin and customer UI can
196	 * render an "(edited)" label — an edit is a transparency signal both parties
197	 * see, unlike the read receipts below which are staff-facing only.
198	 */
199	export async function editTicketMessage(messageId: string, newBody: string): Promise<{ error?: string }> {
200	  const user = await requireUser();
201	  const body = newBody.trim();
202	  if (body.length < 2 || body.length > 10000) return { error: "Message must be between 2 and 10,000 characters." };
203	
204	  const message = await db.ticketMessage.findUnique({
205	    where: { id: messageId },
206	    include: { ticket: { select: { id: true, status: true } } },
207	  });
208	  if (!message) return { error: "Message not found." };
209	  if (message.authorId !== user.id) return { error: "You can only edit your own messages." };
210	  if (message.ticket.status === "CLOSED") return { error: "This ticket is closed." };
211	  if (Date.now() - message.createdAt.getTime() >= EDIT_WINDOW_MS) {
212	    return { error: "You can only edit a message within 5 minutes of sending it." };
213	  }
214	
215	  await db.ticketMessage.update({ where: { id: messageId }, data: { body, editedAt: new Date() } });
216	  revalidatePath(`/dashboard/support/${message.ticket.id}`);
217	  revalidatePath(`/admin/support/${message.ticket.id}`);
218	  return {};
219	}
220	
221	/**
222	 * Stamp `readAt` on every unread STAFF message in this ticket — called once
223	 * from app/dashboard/support/[id]/page.tsx when the CUSTOMER who owns the
224	 * ticket views it. Deliberately one-directional: there is no equivalent call
225	 * for staff viewing a customer's messages, per the explicit design ("read
226	 * receipts from customers, but they dont get them from us") — staff sees when
227	 * the customer has read a staff reply; the customer never sees a receipt at all.
228	 */
229	export async function markTicketMessagesRead(ticketId: string): Promise<void> {
230	  const user = await requireUser();
231	  const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
232	  if (!ticket || ticket.userId !== user.id) return; // silently a no-op for anyone but the owning customer
233	  await db.ticketMessage.updateMany({
234	    where: { ticketId, isStaff: true, readAt: null },
235	    data: { readAt: new Date() },
236	  });
237	}
238

250	    orderBy: { createdAt: "asc" },
251	    select: { address: true, passwordEnc: true },
252	  });
253	
254	  if (boxes.length === 0) {
255	    const unverified = subs.filter((s) => !s.verified).map((s) => s.domainName);
256	    const verified = subs.filter((s) => s.verified).map((s) => s.domainName);
257	    // An unverified domain is the more actionable problem: no mailbox can even
258	    // be created on it yet, so lead with that.
