162	/**
163	 * Staff reply carrying an image attachment. Same authorization and side effects
164	 * as `replyToConversation` (requireGrant("liveChat"), notify, assign, unread) but
165	 * the message body may be empty and it stores a signature-verified image in
166	 * Postgres. All security checks (allow-list, magic-number, 5 MB cap, SVG
167	 * rejection) run in `validateImageBytes` — the client cannot bypass them.
168	 */
169	export async function replyWithAttachment(
170	  formData: FormData
171	): Promise<{ error?: string; ok?: boolean }> {
172	  const staff = await requireGrant("liveChat");
173	
174	  // Throttle staff uploads defensively (shared limiter, keyed by staff id).
175	  const rl = checkRateLimit(`chat-upload:${staff.id}`, { max: 30, windowMs: 60_000 });
176	  if (!rl.ok) return { error: "Too many uploads. Please slow down." };
177	
178	  const id = formData.get("conversationId");
179	  const rawBody = formData.get("body");
180	  const file = formData.get("file");
181	
182	  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
183	  const body = typeof rawBody === "string" ? rawBody.trim().slice(0, 5000) : "";
184	  if (!(file instanceof File)) return { error: "No image provided." };
185	  if (file.size > 5 * 1024 * 1024) return { error: "Image is larger than 5 MB." };
186	
187	  const convo = await db.chatConversation.findUnique({ where: { id } });
188	  if (!convo) return { error: "Conversation not found." };
189	
190	  const bytes = Buffer.from(await file.arrayBuffer());
191	  const check = validateImageBytes(bytes, file.type);
192	  if (!check.ok) return { error: check.error };
193	
194	  await db.$transaction(async (tx) => {
195	    const msg = await tx.chatMessage.create({
196	      data: { conversationId: id, sender: "agent", body },
197	    });
198	    await tx.chatAttachment.create({
199	      data: {
200	        messageId: msg.id,
201	        mime: check.mime,
202	        sizeBytes: check.bytes.length,
203	        data: new Uint8Array(check.bytes),
204	      },
205	    });
206	    await tx.chatConversation.update({
207	      where: { id },
208	      data: {
209	        status: "OPEN",
210	        unreadForUser: true,
211	        unreadForAgent: false,
212	        assignedToId: staff.id,
213	        lastMessageAt: new Date(),
214	      },
215	    });
216	  });
217	
218	  if (convo.userId) {
219	    await db.notification
220	      .create({
221	        data: {
222	          userId: convo.userId,
223	          title: "New reply in your live chat",
224	          href: "/dashboard",
225	        },
226	      })
227	      .catch(() => {});
228	  }
229	
230	  // Discord bridge (Phase 1 mirror): the bridge doesn't forward image bytes
231	  // (see lib/discord-bridge.ts), so mirror a short placeholder plus any caption.
232	  await mirrorChatMessageToDiscord(id, body ? `📎 ${body}` : "📎 (image attachment — view in /admin/chat)", "agent");
233	
234	  revalidatePath("/admin/chat");
235	  return { ok: true };
236	}
