317	/**
318	 * Transfer a live-chat conversation into a support ticket (admin inbox
319	 * "Transfer to ticket" button).
320	 *
321	 * Ownership: `Ticket.userId` is required (see `createTicket` in
322	 * lib/actions-support.ts, which never creates a ticket without a real
323	 * `requireUser()`). A signed-in visitor's conversation already carries
324	 * `ChatConversation.userId` (stamped the moment they chat while logged in —
325	 * see POST /api/chat). An anonymous visitor has none, so we make exactly one
326	 * best-effort reconciliation attempt: look up a `User` by the conversation's
327	 * stored email — `User.email` is `@unique`, the same lookup shape used
328	 * elsewhere in the codebase for account matching (e.g. lib/actions.ts,
329	 * lib/actions-partner.ts's team-invite linking). If that still finds nothing,
330	 * the transfer is refused with a clear reason rather than fabricating a guest
331	 * ticket owner.
332	 *
333	 * Message copy: `sender: "visitor"` becomes `isStaff: false` authored by the
334	 * resolved customer; `sender: "agent"` becomes `isStaff: true` authored by
335	 * whichever staff member is assigned to the conversation (falling back to the
336	 * admin performing the transfer, since individual chat messages don't record
337	 * a per-message author — only `ChatConversation.assignedToId` does);
338	 * `sender: "bot"` (the AI assistant) is copied the same way, staff-side, with
339	 * a "[AI reply]" prefix so the ticket transcript doesn't misattribute it to a
340	 * human. Image attachments are NOT copied — `TicketMessage`'s attachment
341	 * columns are separate, actively-changing work in this tree — a
342	 * "[image attachment omitted]" note is left in the message body instead.
343	 * `createdAt` is preserved on every copied message.
344	 */
345	export async function transferChatToTicket(conversationId: string): Promise<{ error?: string }> {
346	  const staff = await requireGrant("liveChat");
347	  if (typeof conversationId !== "string" || !conversationId) return { error: "Invalid conversation." };
348	
349	  const convo = await db.chatConversation.findUnique({
350	    where: { id: conversationId },
351	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
352	  });
353	  if (!convo) return { error: "Conversation not found." };
354	
355	  let matchedId = convo.userId;
356	  if (!matchedId && convo.email) {
357	    const matched = await db.user.findUnique({ where: { email: convo.email }, select: { id: true } });
358	    matchedId = matched?.id ?? null;
359	  }
360	  if (!matchedId) {
361	    return {
362	      error:
363	        `This chat isn't linked to a customer account yet — no account matches ` +
364	        `${convo.email ? `"${convo.email}"` : "this visitor"}. Ask them to sign in ` +
365	        `(or confirm their email) before transferring it to a ticket.`,
366	    };
367	  }
368	  const ownerId: string = matchedId;
369	
370	  const firstVisitorMsg = convo.messages.find((m) => m.sender === "visitor" && m.body.trim());
371	  const subject = (firstVisitorMsg?.body.trim() || "Live chat conversation").slice(0, 140);
372	
373	  const ticketMessages = convo.messages
374	    .map((m) => {
375	      let body = m.body?.trim() ?? "";
376	      if (m.attachment) body = body ? `${body}\n[image attachment omitted]` : "[image attachment omitted]";
377	      if (!body) return null;
378	      const isStaff = m.sender !== "visitor"; // "agent" and "bot" both sit on the business side
379	      const authorId =
380	        m.sender === "visitor" ? ownerId : m.sender === "agent" ? convo.assignedToId || staff.id : staff.id;
381	      const finalBody = m.sender === "bot" ? `[AI reply] ${body}` : body;
382	      return { body: finalBody.slice(0, 10000), isStaff, authorId, createdAt: m.createdAt };
383	    })
384	    .filter((m): m is NonNullable<typeof m> => m !== null);
385	
386	  const TRANSFER_NOTICE =
387	    "This conversation was transferred to a support ticket — an agent will follow up there.";
388	
389	  const ticket = await db.$transaction(async (tx) => {
390	    const t = await tx.ticket.create({
391	      data: {
392	        subject,
393	        priority: "NORMAL",
394	        userId: ownerId,
395	        messages: { create: ticketMessages },
396	      },
397	    });
398	    await tx.chatMessage.create({
399	      data: { conversationId: convo.id, sender: "bot", body: TRANSFER_NOTICE },
400	    });
401	    await tx.chatConversation.update({
402	      where: { id: convo.id },
403	      data: { status: "CLOSED", unreadForAgent: false },
404	    });
405	    return t;
406	  });
407	
408	  await db.notification
409	    .createMany({
410	      data: (await db.user.findMany({ where: { role: "ADMIN" } })).map((a) => ({
411	        userId: a.id,
412	        title: `New ticket (from chat): ${subject}`,
413	        href: `/admin/support/${ticket.id}`,
414	      })),
415	    })
416	    .catch(() => {});
417	
418	  revalidatePath("/admin/chat");
419	  revalidatePath("/admin/support");
420	  revalidatePath("/staff/chat");
421	  revalidatePath("/staff/support");
422	  // A granted EMPLOYEE transferring from the staff portal has no /admin
423	  // access at all — landing them on /admin/support/[id] would just bounce
424	  // them straight back out via that route's own gate. Route by the acting
425	  // staffer's role, same convention as requireAreaOrGrant's own redirects.
426	  redirect(staff.role === "EMPLOYEE" ? `/staff/support/${ticket.id}` : `/admin/support/${ticket.id}`);
427	}
