3	import { randomBytes } from "node:crypto";
4	import { revalidatePath } from "next/cache";
5	import { z } from "zod";
6	import bcrypt from "bcryptjs";
7	import type { Role } from "@prisma/client";
8	import { db } from "./db";
9	import { requireAdmin } from "./auth";
10	import { normalizeEmail } from "./email-normalize";
11	import { normalizeCidr } from "./firewall-rules";
12	import { GRANTABLE_AREAS } from "./staff-grants";
13	import type { Area } from "./rbac";
14	
15	const roleSchema = z.enum(["CUSTOMER", "SUPPORT", "BILLING", "ADMIN"]);
16	
17	/**
18	 * Promote/demote a user's role. ADMIN-only, audit-logged. An admin can't
19	 * change their own role (prevents locking yourself out of admin).
20	 */
21	export async function setUserRole(
22	  userId: string,
23	  role: Role,
24	): Promise<{ ok?: boolean; error?: string }> {
25	  const admin = await requireAdmin();
26	
27	  const parsed = roleSchema.safeParse(role);
28	  if (!parsed.success) return { error: "Invalid role." };
29	
30	  if (userId === admin.id) return { error: "You can't change your own role." };
31	
32	  const target = await db.user.findUnique({ where: { id: userId } });
33	  if (!target) return { error: "User not found." };
34	  if (target.role === parsed.data) return { ok: true };
35	
36	  await db.user.update({ where: { id: userId }, data: { role: parsed.data } });
37	  await db.auditLog.create({
38	    data: {
39	      userId: admin.id,
40	      action: "staff.setRole",
41	      detail: `${target.email}: ${target.role} → ${parsed.data}`,
42	    },
43	  });
44	
45	  revalidatePath("/admin/staff");
46	  revalidatePath(`/admin/users/${userId}`);
47	  return { ok: true };
48	}
