50	function isGrantableArea(area: unknown): area is Area {
51	  return GRANTABLE_AREAS.some((g) => g.area === area);
52	}
53	
54	/**
55	 * Create a Role.EMPLOYEE account with ZERO access (see lib/staff-grants.ts —
56	 * EMPLOYEE has no area until an explicit StaffGrant exists). The temp password
57	 * is returned to the caller exactly once; only its bcrypt hash is ever stored,
58	 * at the same cost factor (12) as every other password write in this codebase
59	 * (lib/actions.ts's register, lib/actions-account.ts's changePassword) so this
60	 * account is no weaker than one a customer created themselves.
61	 */
62	export async function createEmployee(
63	  email: string,
64	  name: string,
65	): Promise<{ ok: true; tempPassword: string } | { ok: false; error: string }> {
66	  const admin = await requireAdmin();
67	
68	  const cleanEmail = normalizeEmail(email);
69	  const cleanName = String(name ?? "").trim().slice(0, 100);
70	  if (!cleanEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleanEmail)) {
71	    return { ok: false, error: "Enter a valid email address." };
72	  }
73	  if (!cleanName) return { ok: false, error: "Enter a name." };
74	
75	  const existing = await db.user.findUnique({ where: { email: cleanEmail }, select: { id: true } });
76	  if (existing) return { ok: false, error: "An account with that email already exists." };
77	
78	  // base64url so it's copy-pasteable with no shell/URL-escaping surprises.
79	  const tempPassword = randomBytes(9).toString("base64url");
80	  const employee = await db.user.create({
81	    data: {
82	      email: cleanEmail,
83	      name: cleanName,
84	      role: "EMPLOYEE",
85	      passwordHash: await bcrypt.hash(tempPassword, 12),
86	    },
87	  });
88	
89	  await db.auditLog.create({
90	    data: { userId: admin.id, action: "staff.createEmployee", detail: `${employee.email} (${employee.id})` },
91	  });
92	
93	  revalidatePath("/admin/staff");
94	  return { ok: true, tempPassword };
95	}
96	
97	/**
98	 * Grant/revoke ONE area for ONE employee. This is the single write path for
99	 * StaffGrant — every area an EMPLOYEE ever reaches traces back to a row this
100	 * function wrote, which is what makes the audit log below a complete history
101	 * of who could do what and when.
102	 *
103	 * Deliberately refuses non-EMPLOYEE targets: hasAreaAccess() in
104	 * lib/staff-grants.ts only ever consults StaffGrant for role === "EMPLOYEE",
105	 * so a row on a SUPPORT/BILLING/ADMIN account would silently do nothing —
106	 * an error here is more honest than a checkbox that appears to save but never
107	 * has any effect.
108	 */
109	export async function setStaffGrant(
110	  userId: string,
111	  area: Area,
112	  granted: boolean,
113	): Promise<{ ok?: boolean; error?: string }> {
114	  const admin = await requireAdmin();
115	
116	  if (!isGrantableArea(area)) return { error: "Not a grantable area." };
117	
118	  const target = await db.user.findUnique({ where: { id: userId }, select: { role: true, email: true } });
119	  if (!target) return { error: "User not found." };
120	  if (target.role !== "EMPLOYEE") return { error: "Grants only apply to Role.EMPLOYEE accounts." };
121	
122	  if (granted) {
123	    await db.staffGrant.upsert({
124	      where: { userId_area: { userId, area } },
125	      create: { userId, area, createdById: admin.id },
126	      update: {},
127	    });
128	  } else {
129	    await db.staffGrant.deleteMany({ where: { userId, area } });
130	  }
131	
132	  await db.auditLog.create({
133	    data: { userId: admin.id, action: "staff.setGrant", detail: `${target.email}: ${area} → ${granted}` },
134	  });
135	
136	  revalidatePath(`/admin/staff/${userId}`);
137	  return { ok: true };
138	}
139	
140	/**
141	 * Add one CIDR to an employee's staff-portal IP allowlist. `normalizeCidr`
142	 * (lib/firewall-rules.ts) is the same gate the guest firewall uses — reused
143	 * rather than reimplemented so a "valid CIDR" can never mean two different
144	 * things in this codebase.
145	 */
146	export async function addStaffIp(
147	  userId: string,
148	  cidr: string,
149	  label?: string,
150	): Promise<{ ok?: boolean; error?: string }> {
151	  const admin = await requireAdmin();
152	
153	  const target = await db.user.findUnique({ where: { id: userId }, select: { role: true, email: true } });
154	  if (!target) return { error: "User not found." };
155	  if (target.role !== "EMPLOYEE") return { error: "IP allowlists only apply to Role.EMPLOYEE accounts." };
156	
157	  const normalized = normalizeCidr(cidr);
158	  if (!normalized) {
159	    return { error: "Enter a valid IPv4 address or CIDR range (e.g. 203.0.113.4 or 203.0.113.0/24)." };
160	  }
161	
162	  const duplicate = await db.staffIpAllow.findFirst({ where: { userId, cidr: normalized }, select: { id: true } });
163	  if (duplicate) return { error: "That range is already on the list." };
164	
165	  await db.staffIpAllow.create({
166	    data: { userId, cidr: normalized, label: label?.trim().slice(0, 80) || null },
167	  });
168	  await db.auditLog.create({
169	    data: { userId: admin.id, action: "staff.addIp", detail: `${target.email}: ${normalized}` },
170	  });
171	
172	  revalidatePath(`/admin/staff/${userId}`);
173	  return { ok: true };
174	}
