176	export async function removeStaffIp(userId: string, id: string): Promise<{ ok?: boolean; error?: string }> {
177	  const admin = await requireAdmin();
178	
179	  const row = await db.staffIpAllow.findUnique({ where: { id }, select: { userId: true, cidr: true } });
180	  if (!row || row.userId !== userId) return { error: "Not found." };
181	
182	  await db.staffIpAllow.delete({ where: { id } });
183	  await db.auditLog.create({
184	    data: { userId: admin.id, action: "staff.removeIp", detail: `user=${userId}: ${row.cidr}` },
185	  });
186	
187	  revalidatePath(`/admin/staff/${userId}`);
188	  return { ok: true };
189	}
