5	/**
6	 * Per-employee IP allow-list gate for /staff, structurally parallel to
7	 * app/admin/layout.tsx's adminIpBlocked but scoped to one user's own
8	 * StaffIpAllow rows instead of a single global setting.
9	 *
10	 * Zero rows for this user = no restriction (fail OPEN) — a brand-new
11	 * employee isn't locked out before an admin gets around to configuring their
12	 * IPs. The moment even one row exists for THIS specific user, only a request
13	 * from an IP inside one of their allowed ranges is accepted (fail CLOSED);
14	 * every other employee with no rows of their own is completely unaffected,
15	 * since this only ever reads rows for the passed-in userId.
16	 *
17	 * Returns true when access should be REFUSED.
18	 */
19	export async function staffIpBlocked(userId: string): Promise<boolean> {
20	  const rows = await db.staffIpAllow.findMany({ where: { userId }, select: { cidr: true } });
21	  if (rows.length === 0) return false;
22	
23	  const hdrs = await headers();
24	  // Trust nginx's X-Real-IP ($remote_addr), which the client cannot forge. Fall
25	  // back to the LAST X-Forwarded-For hop (the one our proxy appended), never the
26	  // client-supplied leftmost entry. Same anti-spoofing trust model as
27	  // app/admin/layout.tsx's adminIpBlocked.
28	  const xff = (hdrs.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
29	  const ip = hdrs.get("x-real-ip")?.trim() || xff[xff.length - 1] || "";
30	  if (!ip) {
31	    console.warn("[staff-ip] could not determine requester IP; failing open for user", userId);
32	    return false;
33	  }
34	
35	  return !rows.some((r) => ipInCidr(ip, r.cidr));
36	}
