117	/**
118	 * The single validation gate. Returns a normalised ValidatedRule or a
119	 * customer-facing error string. Used by the action (before persisting) AND the
120	 * worker (before building the script) so the two can never disagree.
121	 */
122	export function validateRule(raw: RawRule): ValidateResult {
123	  const action = String(raw.action ?? "").toUpperCase();
124	  if (!FW_ACTIONS.includes(action as FwAction)) {
125	    return { ok: false, error: "Action must be Allow or Deny." };
126	  }
127	  const protocol = String(raw.protocol ?? "").toUpperCase();
128	  if (!FW_PROTOCOLS.includes(protocol as FwProtocol)) {
129	    return { ok: false, error: "Protocol must be TCP, UDP, ICMP or ALL." };
130	  }
131	
132	  const sourceCidr = normalizeCidr(raw.sourceCidr ?? "0.0.0.0/0");
133	  if (!sourceCidr) {
134	    return {
135	      ok: false,
136	      error: "Source must be a valid IPv4 address or CIDR range (e.g. 0.0.0.0/0 or 203.0.113.4/32).",
137	    };
138	  }
139	
140	  // Ports only apply to TCP/UDP. For ICMP/ALL they are forced to null so a
141	  // stray value can never be smuggled into an iptables invocation that ignores
142	  // --dport anyway.
143	  if (protocol === "ICMP" || protocol === "ALL") {
144	    return {
145	      ok: true,
146	      rule: { action: action as FwAction, protocol: protocol as FwProtocol, portFrom: null, portTo: null, sourceCidr },
147	    };
148	  }
149	
150	  const rawFrom = toIntOrNull(raw.portFrom);
151	  const rawTo = toIntOrNull(raw.portTo);
152	  if (rawFrom === undefined || rawTo === undefined) {
153	    return { ok: false, error: "Ports must be whole numbers." };
154	  }
155	
156	  let portFrom = rawFrom;
157	  let portTo = rawTo;
158	  // "all ports" is a legitimate TCP/UDP rule (e.g. allow all TCP from an office IP).
159	  if (portFrom === null && portTo === null) {
160	    return {
161	      ok: true,
162	      rule: { action: action as FwAction, protocol: protocol as FwProtocol, portFrom: null, portTo: null, sourceCidr },
163	    };
164	  }
165	  // A single port typed into "from" only.
166	  if (portFrom !== null && portTo === null) portTo = portFrom;
167	  if (portFrom === null && portTo !== null) portFrom = portTo;
168	
169	  if (portFrom! < 1 || portFrom! > 65535 || portTo! < 1 || portTo! > 65535) {
170	    return { ok: false, error: "Ports must be between 1 and 65535." };
171	  }
172	  if (portTo! < portFrom!) {
173	    return { ok: false, error: "The port range end must be greater than or equal to the start." };
174	  }
175	
176	  return {
177	    ok: true,
178	    rule: { action: action as FwAction, protocol: protocol as FwProtocol, portFrom, portTo, sourceCidr },
179	  };
180	}
