182	/**
183	 * The iptables arguments for one validated rule, AFTER `-A <CHAIN>`.
184	 * Every element is a validated primitive; there is no customer free text here.
185	 */
186	export function ruleToArgs(rule: ValidatedRule): string[] {
187	  const args: string[] = ["-s", rule.sourceCidr];
188	  if (rule.protocol !== "ALL") {
189	    args.push("-p", rule.protocol.toLowerCase());
190	  }
191	  if ((rule.protocol === "TCP" || rule.protocol === "UDP") && rule.portFrom !== null && rule.portTo !== null) {
192	    const spec = rule.portFrom === rule.portTo ? String(rule.portFrom) : `${rule.portFrom}:${rule.portTo}`;
193	    args.push("--dport", spec);
194	  }
195	  args.push("-j", rule.action === "ALLOW" ? "ACCEPT" : "DROP");
196	  return args;
197	}
