204	/**
205	 * Build the idempotent reconcile script for a guest.
206	 *
207	 * Model: a dedicated chain (NXEON_FW) is created once and INPUT is made to jump
208	 * to it exactly once, at the top. On every sync the chain is FLUSHED and rebuilt
209	 * from scratch, so re-running with the same rule set yields the identical kernel
210	 * state (idempotent) and a partial previous run cannot accumulate stale rules.
211	 * Only OUR chain is ever flushed — the customer's own INPUT rules are untouched.
212	 *
213	 * Baseline (always, before any customer rule):
214	 *   - accept loopback
215	 *   - accept ESTABLISHED,RELATED (so existing/return traffic never breaks)
216	 *   - accept tcp/22  ← ANTI-LOCKOUT: SSH stays reachable no matter what the
217	 *     customer configures; a DENY on 22 can therefore never strand them.
218	 *
219	 * Customer rules follow in `position` order; iptables is first-match-wins, so
220	 * that order is the precedence the UI lets them control.
221	 *
222	 * Trailing default: a final DROP is appended ONLY when the customer has at least
223	 * one ALLOW rule (i.e. they have opted into whitelist / security-group
224	 * semantics). With only DENY rules, or none, the chain RETURNs and the packet
225	 * continues through the guest's own INPUT rules — so enabling the feature can
226	 * never silently black-hole a service the customer was already running.
227	 *
228	 * `rules` MUST be pre-validated (worker re-runs `validateRule` on each row).
229	 */
230	export function buildReconcileScript(rules: ValidatedRule[]): string {
231	  const lines: string[] = [];
232	  lines.push("set -o pipefail");
233	  lines.push("IPT=iptables");
234	  lines.push(`CHAIN=${FW_CHAIN}`);
235	  // Create the chain if missing (ignore "exists"), and jump INPUT → CHAIN once,
236	  // inserted at the top so our decisions run before the guest's own rules.
237	  lines.push('"$IPT" -N "$CHAIN" 2>/dev/null || true');
238	  lines.push('"$IPT" -C INPUT -j "$CHAIN" 2>/dev/null || "$IPT" -I INPUT 1 -j "$CHAIN"');
239	  // Rebuild our chain from scratch — the only flush, and only of our chain.
240	  lines.push('"$IPT" -F "$CHAIN"');
241	  lines.push('"$IPT" -A "$CHAIN" -i lo -j ACCEPT');
242	  lines.push('"$IPT" -A "$CHAIN" -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT');
243	  for (const p of FW_KEEP_OPEN_TCP_PORTS) {
244	    lines.push(`"$IPT" -A "$CHAIN" -p tcp --dport ${p} -j ACCEPT`);
245	  }
246	  for (const rule of rules) {
247	    lines.push(['"$IPT"', "-A", '"$CHAIN"', ...ruleToArgs(rule)].join(" "));
248	  }
249	  if (hasAnyAllow(rules)) {
250	    lines.push('"$IPT" -A "$CHAIN" -j DROP');
251	  }
252	  return lines.join("\n");
253	}
