import { requireAreaOrGrant } from "@/lib/staff-grants";
import { listRedditTree, getRedditSelection } from "@/lib/actions-reddit-templates";
import { RedditClient } from "@/components/admin/RedditClient";

export const dynamic = "force-dynamic";

/**
 * Employee-portal Reddit template library. This page is a deliberate light
 * duplicate of app/admin/reddit/page.tsx rather than an extracted shared
 * component — that page is already thin (all the real logic lives in
 * RedditClient), so a second three-line page costs less than a wrapper would.
 * RedditClient itself takes no admin-only prop and every export it calls in
 * lib/actions-reddit-templates.ts is requireGrant("redditTemplates")-gated
 * (Phase 2), so a granted EMPLOYEE using it here is exactly as safe as an
 * ADMIN using it in /admin/reddit — it's a static content library with no
 * customer data and no live posting.
 */
export default async function StaffRedditPage() {
  await requireAreaOrGrant("redditTemplates");

  const tree = await listRedditTree();
  const first = tree[0] ?? null;
  const initialSelected = first ? { categoryId: first.id, subcategoryId: null } : null;
  const initialSelection = initialSelected ? await getRedditSelection(initialSelected.categoryId, initialSelected.subcategoryId) : null;

  return <RedditClient initialTree={tree} initialSelected={initialSelected} initialSelection={initialSelection} />;
}

