import { PageHeader, Badge } from "@/components/ui/primitives";
import { listCompanyMailboxes } from "@/lib/actions-company-mail";
import { COMPANY_MAIL_DOMAIN } from "@/lib/company-mail-core";
import { CompanyMailboxes } from "@/components/admin/CompanyMailboxes";

export const dynamic = "force-dynamic";
export const metadata = { title: "Mailboxes" };

/**
 * Employee-portal mailbox management. Identical gate and identical data as
 * app/admin/mailboxes/page.tsx — both reuse CompanyMailboxes directly (it's
 * already a self-contained client component, no extraction needed). Only
 * `webmailUrl` differs: this points at /staff/inbox, not /admin/inbox.
 */
const WEBMAIL_URL = "/staff/inbox";

export default async function StaffMailboxesPage() {
  await requireAreaOrGrant("companyMailboxes");
  const rows = await listCompanyMailboxes();

  return (
    <div className="space-y-6">
      <PageHeader
        title="Mailboxes"
        sub={`Company email accounts on ${COMPANY_MAIL_DOMAIN} — free, not tied to any customer plan or billing.`}
      >
        <Badge tone="green">free</Badge>
      </PageHeader>

      <div className="card p-4">
        <p className="text-sm text-slate-300">
          Create and manage the company&apos;s own mailboxes (admin@, support@, santino@, and any others).
          They&apos;re provisioned on the Nxeon mail server and never charged. Read and send from them right here in
          the staff portal —{" "}
          <a href={WEBMAIL_URL} className="text-brand-300 hover:underline">
            open the Inbox
          </a>{" "}
          and pick the mailbox from the switcher (no separate login). The password below is only needed for external
          mail clients.

