15	 * the "manage mailboxes" links point — /admin/mailboxes for the ops portal,
16	 * /staff/mailboxes for the employee portal (only reachable there if that
17	 * specific EMPLOYEE also holds the companyMailboxes grant; if not, the link
18	 * simply 403s them same as hand-typing the URL would).
19	 */
20	export async function CompanyInboxView({
21	  requestedMailbox,
22	  mailboxesHref,
23	}: {
24	  requestedMailbox?: string;
25	  mailboxesHref: string;
26	}) {
27	  const company = await listCompanyMailboxes();
28	  if (company.length === 0) {
29	    return (
30	      <div className="space-y-6">
31	        <PageHeader title="Company inbox" sub="Read and send from the company mailboxes." />
32	        <div className="card flex flex-col items-center justify-center py-14 text-center">
33	          <h3 className="text-base font-semibold">No mailboxes yet</h3>
34	          <p className="mt-1 max-w-sm text-sm text-slate-400">
35	            Create a company mailbox first, then read its mail here.
36	          </p>
37	          <Link href={mailboxesHref} className="btn-primary mt-5">
38	            Manage mailboxes
39	          </Link>
40	        </div>
41	      </div>
42	    );
43	  }
44	
45	  // The switcher shows only the company mailboxes (with their live quota usage).
46	  const mailboxes: MailboxInfo[] = company.map((c) => ({
47	    address: c.address,
48	    usedBytes: (c.usedMB ?? 0) * 1024 * 1024,
49	    quotaBytes: c.quotaMB * 1024 * 1024,
50	  }));
51	
52	  // Which mailbox to open first. Honour `?mailbox=` when it names a real company
53	  // mailbox; otherwise start on the first one (listCompanyMailboxes orders by
54	  // address asc, so this is stable). We then try that mailbox and — if it can't
55	  // be reached — fall back to the remaining ones IN ORDER.
56	  //
57	  // WHY the fallback: a company mailbox that can't be opened (its Mailcow
58	  // password was rotated out-of-band, the box is mid-provision, a transient IMAP
59	  // hiccup) used to dead-end the WHOLE inbox on the error card below — even
60	  // though there are three other perfectly readable company mailboxes. One bad
61	  // default made every company mailbox unreadable in the portal. Landing on the
62	  // first mailbox that actually loads keeps the inbox usable; the switcher
63	  // still lists them all, so staff can jump to any specific one.
64	  const wanted = requestedMailbox?.trim().toLowerCase();
65	  const preferred =
66	    wanted && mailboxes.some((m) => m.address.toLowerCase() === wanted) ? wanted : mailboxes[0].address;
67	  const candidates = [preferred, ...mailboxes.map((m) => m.address).filter((a) => a !== preferred)];
68	
69	  let active = preferred;
70	  let folders: MailFolder[] = [];
71	  let list: ListResult = { messages: [], total: 0, page: 1, pageSize: 25 };
72	  let inboxPath = "INBOX";
73	
74	  for (const address of candidates) {
75	    try {
76	      const f = await listFolders(address);
77	      if (f.length === 0) continue;
78	      const path = f.find((x) => x.role === "inbox")?.path ?? f[0]?.path ?? "INBOX";
79	      const msgs = await listMessages(path, 1, undefined, address);
80	      active = address;
81	      folders = f;
82	      inboxPath = path;
83	      list = msgs;
84	      break;
85	    } catch {
86	      // Try the next company mailbox; only report failure if none load.
87	    }
88	  }
89	
90	  if (folders.length === 0) {
91	    return (
92	      <div className="space-y-6">
93	        <PageHeader title="Company inbox" sub={preferred} />
94	        <div className="card p-6 text-center text-sm text-slate-400">
95	          Couldn&apos;t reach the mail server for any company mailbox.
96	          If a mailbox was just created, give it a moment and reload; otherwise reset its password on the{" "}
97	          <Link href={mailboxesHref} className="text-brand-300 hover:underline">
98	            Mailboxes
99	          </Link>{" "}
100	          page.
101	        </div>
102	      </div>
103	    );
104	  }
105	
106	  // The content area is full-bleed (Shell renders /admin/inbox and /staff/inbox
107	  // in an `overflow-hidden flex-1` <main>, see components/portal/Shell.tsx).
108	  // Sizing to the viewport minus the header (4rem) plus a small margin keeps the
109	  // whole mail surface inside the content area; MailClient is `h-full`
110	  // internally and scrolls its own panes.
111	  //
112	  // NOTE: the admin ops portal additionally stacks an <AdminSubTabs> bar above
113	  // this component inside that same <main> (Inbox / Deliverability / Mailboxes
114	  // / Email templates), which is why app/admin/inbox/page.tsx historically sized
115	  // this to `calc(100vh-8.5rem)`. The employee portal has no such sub-tab bar,
116	  // so it sizes to `calc(100vh-4.5rem)` (matching /staff/reddit's own full-bleed
117	  // sizing) instead — this component doesn't know which portal it's in, so both
118	  // callers wrap it with their own height, not this component itself.
119	  return (
120	    <MailClient
121	      initialFolders={folders}
122	      initialMailboxes={mailboxes}
123	      initialList={list}
124	      initialFolderPath={inboxPath}
125	      initialActiveAddress={active}
126	      loadMailboxes={listCompanyMailboxInfos}
127	    />
128	  );
129	}
