3	import { useEffect, useState } from "react";
4	import { listCannedReplies, type CannedReplyItem } from "@/lib/actions-canned-replies";
5	
6	/**
7	 * Quick-replies snippet picker, shared between the ticket reply form
8	 * (components/admin/TicketControls.tsx) and the live-chat reply box
9	 * (components/admin/ChatInbox.tsx). v1 on purpose: a plain `<select>` that
10	 * appends the chosen snippet's body onto whatever the agent has already
11	 * typed — no rich-text merge, no keyboard-shortcut trigger. The list loads
12	 * client-side via `listCannedReplies` (already gated
13	 * requireAnyGrant(["supportTickets","liveChat"]) in
14	 * lib/actions-canned-replies.ts), so this renders nothing extra for a caller
15	 * who somehow reaches it without either grant — the action call simply
16	 * throws and the catch below leaves the picker empty rather than crashing
17	 * the reply box around it.
18	 */
19	export function CannedReplyPicker({
20	  onInsert,
21	  disabled,
22	}: {
23	  onInsert: (body: string) => void;
24	  disabled?: boolean;
25	}) {
26	  const [replies, setReplies] = useState<CannedReplyItem[]>([]);
27	
28	  useEffect(() => {
29	    let alive = true;
30	    listCannedReplies()
31	      .then((rows) => alive && setReplies(rows))
32	      .catch(() => {});
33	    return () => {
34	      alive = false;
35	    };
36	  }, []);
37	
38	  if (replies.length === 0) return null;
39	
40	  return (
41	    <select
42	      aria-label="Insert a canned reply"
43	      className="input w-auto py-1.5 text-xs"
44	      value=""
45	      disabled={disabled}
46	      onChange={(e) => {
47	        const reply = replies.find((r) => r.id === e.target.value);
48	        if (reply) onInsert(reply.body);
49	        e.target.value = "";
50	      }}
51	    >
52	      <option value="" disabled>
53	        Insert canned reply…
54	      </option>
55	      {replies.map((r) => (
56	        <option key={r.id} value={r.id}>
57	          {r.title}
58	        </option>
59	      ))}
60	    </select>
61	  );
62	}
