255	/** Reorder a column within its board; renumber siblings (full-list-renumber,
256	 *  same strategy as components/admin/BoardClient.tsx's moveColumn). */
257	export async function moveColumn(columnId: string, toIndex: number): Promise<void> {
258	  const actor = await requireGrant("tasks");
259	  const col = await db.workColumn.findUnique({ where: { id: columnId }, select: { boardId: true } });
260	  if (!col) return;
261	  const siblings = await db.workColumn.findMany({
262	    where: { boardId: col.boardId, NOT: { id: columnId } },
263	    orderBy: { position: "asc" },
264	    select: { id: true },
265	  });
266	  const order = siblings.map((s) => s.id);
267	  const idx = Math.max(0, Math.min(toIndex, order.length));
268	  order.splice(idx, 0, columnId);
269	  await db.$transaction(order.map((id, i) => db.workColumn.update({ where: { id }, data: { position: i } })));
270	  await audit(actor.id, "task.column.move", columnId);
271	  refreshBoardPaths();
272	}
