349	/** Edit a task's title and/or description. Not part of the original "one verb
350	 *  per mutation" list but genuinely required for this to be a real task tool —
351	 *  the schema's `description` field would otherwise be permanently unreachable. */
352	export async function updateTask(taskId: string, patch: { title?: string; description?: string }): Promise<{ error?: string }> {
353	  const actor = await requireGrant("tasks");
354	  const data: Record<string, string> = {};
355	  if (patch.title !== undefined) {
356	    const t = patch.title.trim().slice(0, 200);
357	    if (!t) return { error: "Title can't be empty." };
358	    data.title = t;
359	  }
360	  if (patch.description !== undefined) data.description = patch.description.slice(0, 20_000);
361	  if (Object.keys(data).length === 0) return {};
362	  await db.workTask.update({ where: { id: taskId }, data }).catch(() => undefined);
363	  await audit(actor.id, "task.update", taskId);
364	  refreshBoardPaths();
365	  return {};
