368	/** Move a task to a column at a position; renumber siblings (full-list-renumber,
369	 *  same strategy as lib/actions-board.ts's moveCard — dnd-kit drives the drag
370	 *  gesture, this is the same server-side reorder). */
371	export async function moveTask(taskId: string, toColumnId: string, toIndex: number): Promise<void> {
372	  const actor = await requireGrant("tasks");
373	  const task = await db.workTask.findUnique({ where: { id: taskId }, select: { columnId: true, boardId: true } });
374	  const col = await db.workColumn.findUnique({ where: { id: toColumnId }, select: { boardId: true } });
375	  if (!task || !col || col.boardId !== task.boardId) return;
376	  const siblings = await db.workTask.findMany({
377	    where: { columnId: toColumnId, archivedAt: null, NOT: { id: taskId } },
378	    orderBy: { position: "asc" },
379	    select: { id: true },
380	  });
381	  const order = siblings.map((s) => s.id);
382	  const idx = Math.max(0, Math.min(toIndex, order.length));
383	  order.splice(idx, 0, taskId);
384	  await db.$transaction([
385	    db.workTask.update({ where: { id: taskId }, data: { columnId: toColumnId } }),
386	    ...order.map((id, i) => db.workTask.update({ where: { id }, data: { position: i } })),
387	  ]);
388	  await audit(actor.id, "task.move", `${taskId} -> column ${toColumnId}`);
389	  refreshBoardPaths();
390	}
