10	// Videos can be large; everything else is capped tighter. Same caps as the
11	// dev-ops board's own upload route (app/api/board/attachments/route.ts) — no
12	// reason for a staff task attachment to have a different budget.
13	const MAX_VIDEO = 300 * 1024 * 1024;
14	const MAX_OTHER = 50 * 1024 * 1024;
15	
16	function kindFor(mime: string): "IMAGE" | "VIDEO" | "FILE" {
17	  if (mime.startsWith("image/")) return "IMAGE";
18	  if (mime.startsWith("video/")) return "VIDEO";
19	  return "FILE";
20	}
21	
22	/** Upload an attachment to a work task. Gated on the "tasks" grant — reachable
23	 *  by a Role.EMPLOYEE with that grant, not just admin staff. `?taskId=` in the
24	 *  query. Stored on disk under WORK_UPLOAD_DIR (never board-uploads/ — see
25	 *  lib/work-shared.ts). */
26	export async function POST(req: NextRequest) {
27	  let actor;
28	  try {
29	    actor = await requireGrant("tasks");
30	  } catch {
31	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
32	  }
33	  const taskId = req.nextUrl.searchParams.get("taskId") ?? "";
34	  const task = await db.workTask.findUnique({ where: { id: taskId }, select: { id: true } });
35	  if (!task) return NextResponse.json({ error: "Task not found" }, { status: 404 });
36	
37	  const form = await req.formData();
38	  const file = form.get("file");
39	  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });
40	
41	  let mime = file.type || "application/octet-stream";
42	  let kind = kindFor(mime);
43	  const cap = kind === "VIDEO" ? MAX_VIDEO : MAX_OTHER;
44	  if (file.size > cap) return NextResponse.json({ error: `File too large (max ${Math.round(cap / 1024 / 1024)} MB)` }, { status: 413 });
45	
46	  const buf = Buffer.from(await file.arrayBuffer());
47	
48	  // A file that CLAIMS to be an image is served inline by the [id] route, so it
49	  // must be a real raster image — never a scripted SVG (stored XSS in the
50	  // portal origin). Verify by byte signature; SVG has no signature and isn't
51	  // allow-listed, so it's rejected here (same reasoning as the board's route).
52	  if (kind === "IMAGE") {
53	    const sniffed = sniffImageMime(buf);
54	    if (!sniffed || mime === "image/svg+xml" || !isAllowedImageMime(mime)) {
55	      return NextResponse.json({ error: "Only PNG, JPEG, GIF, or WEBP images are allowed." }, { status: 400 });
56	    }
57	    mime = sniffed;
58	    kind = kindFor(mime);
59	  }
60	
61	  const ext = (file.name.match(/\.[A-Za-z0-9]{1,8}$/)?.[0] ?? "").toLowerCase();
62	  const storedName = `${randomBytes(12).toString("hex")}${ext}`;
63	  const dir = join(WORK_UPLOAD_DIR, taskId);
64	  try {
65	    await fs.mkdir(dir, { recursive: true });
66	    await fs.writeFile(join(dir, storedName), buf);
67	  } catch (e) {
68	    console.error("[work] attachment write failed:", e);
69	    return NextResponse.json(
70	      { error: `Couldn't save the file (${(e as NodeJS.ErrnoException)?.code ?? "write error"}). Ensure ${WORK_UPLOAD_DIR} is writable by the web user.` },
71	      { status: 500 },
72	    );
73	  }
74	
75	  const att = await db.workTaskAttachment.create({
76	    data: { taskId, filename: file.name.slice(0, 200), storedName, mime, sizeBytes: file.size, kind, uploadedById: actor.id },
77	  });
78	  await db.auditLog.create({ data: { userId: actor.id, action: "task.attachment.add", detail: `${taskId}: ${att.filename}` } });
79	  return NextResponse.json({ id: att.id, filename: att.filename, kind, mime, sizeBytes: att.sizeBytes, url: `/api/work/attachments/${att.id}` });
80	}
