11	 * exactly which tools this employee can reach. Optimistic toggle (matches
12	 * StaffRoleControls' pattern elsewhere in this file's sibling component): the
13	 * checkbox flips immediately and reverts only if the server actually refuses,
14	 * so a reviewer clicking through a dozen boxes isn't waiting on each one.
15	 */
16	export function StaffGrantChecklist({
17	  userId,
18	  areas,
19	  granted,
20	}: {
21	  userId: string;
22	  areas: GrantableArea[];
23	  granted: Area[];
24	}) {
25	  const [grantedSet, setGrantedSet] = useState<Set<Area>>(new Set(granted));
26	  const [pendingArea, setPendingArea] = useState<Area | null>(null);
27	  const [error, setError] = useState<string | null>(null);
28	  const [, startTransition] = useTransition();
29	
30	  function toggle(area: Area, next: boolean) {
31	    setError(null);
32	    setPendingArea(area);
33	    setGrantedSet((prev) => {
34	      const copy = new Set(prev);
35	      if (next) copy.add(area);
36	      else copy.delete(area);
37	      return copy;
38	    });
39	    startTransition(async () => {
40	      const res = await setStaffGrant(userId, area, next);
41	      setPendingArea(null);
42	      if (res.error) {
43	        setError(res.error);
44	        // The checkbox must never show a grant that isn't real server-side.
45	        setGrantedSet((prev) => {
46	          const copy = new Set(prev);
47	          if (next) copy.delete(area);
48	          else copy.add(area);
49	          return copy;
50	        });
51	      }
52	    });
53	  }
54	
55	  return (
56	    <div className="space-y-2">
57	      {areas.map((a) => {
58	        const checked = grantedSet.has(a.area);
59	        return (
60	          <label
61	            key={a.area}
62	            className="flex cursor-pointer items-start gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] p-3 hover:border-white/[0.12]"
63	          >
