72	              <span className="block text-sm font-medium text-slate-200">{a.label}</span>
73	              {a.hint && <span className="block text-xs text-slate-500">{a.hint}</span>}
74	            </span>
75	          </label>
76	        );
77	      })}
78	      {error && <p className="text-xs text-red-400">{error}</p>}
79	    </div>
80	  );
