 * admin oversight over everything staff do here.
 */
export default async function AdminTasksPage({
  searchParams,
}: {
  searchParams: Promise<{ board?: string; task?: string }>;
}) {
  await requireAreaOrGrant("tasks");
  const sp = await searchParams;

  const boards = await listBoards();
  const activeBoardId = boards.find((b) => b.id === sp.board)?.id ?? boards[0]?.id ?? "";

