/**
 * ADMIN-only preview of the staff-portal Clients (limited) view — lets the
 * owner see exactly what a granted EMPLOYEE would see before turning
 * "clientsBasic" on for anyone. Deliberately gated `requireArea("platform")`
 * from lib/rbac, NOT `requireAreaOrGrant("clientsBasic")` from
 * lib/staff-grants: this preview route itself must stay reachable by ADMIN
 * only, forever, even though `HREF_AREA["/admin/clients-basic"]` maps to the
 * grantable "clientsBasic" area (that mapping exists for the /staff route's
 * own grant check — see lib/rbac.ts — not for gating this admin page).
 *
 * Same `select` as app/staff/clients/page.tsx, byte-for-byte — this preview
 * is only trustworthy if it queries exactly what the employee-facing route
 * queries, not a superset "for admin's convenience".
 */
export default async function AdminClientsBasicPreview() {
  await requireArea("platform");

  const clients = await db.user.findMany({
    select: {
      id: true,
      name: true,
      email: true,
      createdAt: true,
      _count: { select: { tickets: true, servers: true } },
    },
    orderBy: { createdAt: "desc" },
    take: 200,
  });

  return <ClientsBasicView clients={clients} />;
}

